"""AA-X27: Noetherian ACC versus Krull dimension.

Exhaustive finite ideal and prime spectra, quotient/localization
correspondence, plus bounded polynomial-support algebra checks.
These computations are independent checks, not proofs of general
Noetherian or dimension theorems.
"""
from itertools import product
from math import gcd
from pathlib import Path
import re
import unittest

import sympy as sp

ROOT = Path(__file__).resolve().parents[2]
X, Y = sp.symbols("X Y")


def divisors(n):
    return [d for d in range(1, n + 1) if n % d == 0]


def ideal_zn(n, d):
    """Ideal generated by d in Z/nZ, provided d | n."""
    assert n % d == 0
    return frozenset(range(0, n, d))


def prime_by_definition(n, ideal):
    if len(ideal) == n:
        return False
    return all((a*b) % n not in ideal or a in ideal or b in ideal
               for a in range(n) for b in range(n))


def radical_zn(n):
    primes = [ideal_zn(n, d) for d in divisors(n)
              if prime_by_definition(n, ideal_zn(n, d))]
    return frozenset.intersection(*primes) if primes else frozenset(range(n))


def localized_modulus(n, s):
    """Z/nZ[1/s] is Z/mZ; m=1 means the zero ring."""
    return sp.prod(p**e for p, e in sp.factorint(n).items() if s % p != 0)


def killed_by_power(n, s, a):
    factor = 1
    for _ in range(n + 1):
        if factor*a % n == 0:
            return True
        factor = factor*s % n
    return False


def quotient_prime_pullback(n, d):
    """Primes of (Z/n)/(d) pulled back along Z/n -> Z/d."""
    assert n % d == 0
    return {ideal_zn(n, p) for p in sp.factorint(d)}


def multiplication(a, b):
    """F2[x,y]/(x^2,y^2), bit basis 1,x,y,xy."""
    aa, bb = [(a >> i) & 1 for i in range(4)], [(b >> i) & 1 for i in range(4)]
    return (
        aa[0]*bb[0]
        | ((aa[0]*bb[1] ^ aa[1]*bb[0]) << 1)
        | ((aa[0]*bb[2] ^ aa[2]*bb[0]) << 2)
        | ((aa[0]*bb[3] ^ aa[3]*bb[0] ^ aa[1]*bb[2] ^ aa[2]*bb[1]) << 3)
    )


def all_ideals_truncated_plane():
    """Exhaustively test all 2^16 subsets, not just presumed ideals."""
    ideals = []
    for mask in range(1, 1 << 16, 2):
        members = [a for a in range(16) if mask & (1 << a)]
        if any(not mask & (1 << (a ^ b))
               for a in members for b in members):
            continue
        if any(not mask & (1 << multiplication(a, b))
               for a in members for b in range(16)):
            continue
        ideals.append(frozenset(members))
    return ideals


def prime_in_truncated_plane(ideal):
    if len(ideal) == 16:
        return False
    return all(
        multiplication(a, b) not in ideal or a in ideal or b in ideal
        for a in range(16) for b in range(16)
    )


class NoetherianKrullCrossAudit(unittest.TestCase):
    def test_zn_ideal_lattice_and_prime_spectrum(self):
        for n in (2, 4, 6, 12, 18, 30, 36, 48, 72):
            with self.subTest(n=n):
                ideals = [ideal_zn(n, d) for d in divisors(n)]
                self.assertEqual(len(ideals), int(sp.divisor_count(n)))
                self.assertEqual(len(set(ideals)), len(ideals))
                for I in ideals:
                    self.assertIn(0, I)
                    self.assertTrue(all((a+b) % n in I
                                        for a in I for b in I))
                    self.assertTrue(all((a*b) % n in I
                                        for a in I for b in range(n)))
                primes = {I for I in ideals if prime_by_definition(n, I)}
                expected = {ideal_zn(n, p) for p in sp.factorint(n)}
                self.assertEqual(primes, expected)
                self.assertEqual(len(primes), len(sp.factorint(n)))
                # Every nonzero Z/n has dimension 0, including nonreduced n.
                self.assertFalse(any(P < Q for P in primes for Q in primes))
                self.assertEqual(radical_zn(n),
                                 frozenset(a for a in range(n)
                                           if all(a % p == 0
                                                  for p in sp.factorint(n))))

    def test_quotients_correspondence_and_spectrum(self):
        for n in (6, 12, 30, 36, 72):
            ideals = [ideal_zn(n, d) for d in divisors(n)]
            primes = {I for I in ideals if prime_by_definition(n, I)}
            for d in divisors(n):
                with self.subTest(n=n, d=d):
                    kernel = ideal_zn(n, d)
                    # The quotient maps onto Z/d; d=1 gives zero ring.
                    self.assertEqual(len(kernel), n//d)
                    pulled_back = quotient_prime_pullback(n, d)
                    self.assertEqual(pulled_back,
                                     {P for P in primes if kernel <= P})
                    self.assertEqual(len(pulled_back),
                                     len(sp.factorint(d)))
                    for p in sp.factorint(d):
                        self.assertTrue(kernel <= ideal_zn(n, p))

    def test_localization_inverts_s_and_preserves_only_disjoint_primes(self):
        for n in (6, 12, 18, 30, 36, 48, 60, 72):
            for s in (1, 2, 3, 4, 5, 6, 10, 15):
                with self.subTest(n=n, s=s):
                    m = int(localized_modulus(n, s))
                    self.assertEqual(n % m, 0)
                    # m=1 is zero ring and Krull dimension is undefined
                    # under the source chapter's explicit convention.
                    self.assertEqual(gcd(s, m), 1)
                    for a in range(n):
                        self.assertEqual(killed_by_power(n, s, a),
                                         a % m == 0)
                    surviving = {p for p in sp.factorint(n)
                                 if s % p != 0}
                    self.assertEqual(surviving, set(sp.factorint(m)))
                    original_primes = {
                        ideal_zn(n, p) for p in sp.factorint(n)}
                    pulled_primes = {
                        ideal_zn(n, p) for p in surviving}
                    self.assertEqual(pulled_primes, {
                        P for P in original_primes if s % n not in P
                    })

    def test_complete_16_element_artinian_ideal_lattice(self):
        ideals = all_ideals_truncated_plane()
        self.assertEqual(len(ideals), 7)
        maximal = frozenset(a for a in range(16) if a & 1 == 0)
        primes = [I for I in ideals if prime_in_truncated_plane(I)]
        self.assertEqual(primes, [maximal])
        self.assertEqual(len(maximal), 8)
        self.assertTrue(all(multiplication(a, b) == multiplication(b, a)
                            for a in range(16) for b in range(16)))
        self.assertTrue(all(multiplication(a, 1) == a for a in range(16)))
        # Nilradical is m: every element of m is nilpotent;
        # elements outside m have constant term 1 and are units.
        self.assertTrue(all(multiplication(multiplication(a, a), a) == 0
                            for a in maximal))
        self.assertTrue(all(multiplication(a, a) == 1
                            for a in range(16) if a & 1))
        # There is exactly one prime, hence no strict prime chains.
        self.assertFalse(any(P < Q for P in primes for Q in primes))

    def test_finite_local_ring_maximal_ideal_not_principal(self):
        ideals = all_ideals_truncated_plane()
        maximal = frozenset(a for a in range(16) if a & 1 == 0)
        self.assertIn(maximal, ideals)
        principal = {
            frozenset(multiplication(a, b) for b in range(16))
            for a in range(16)
        }
        self.assertNotIn(maximal, principal)
        ideal_x = frozenset(multiplication(2, b) for b in range(16))
        ideal_y = frozenset(multiplication(4, b) for b in range(16))
        ideal_xy = frozenset(multiplication(8, b) for b in range(16))
        self.assertEqual(ideal_x, frozenset((0, 2, 8, 10)))
        self.assertEqual(ideal_y, frozenset((0, 4, 8, 12)))
        self.assertEqual(ideal_xy, frozenset((0, 8)))
        self.assertTrue(ideal_xy < ideal_x < maximal)
        self.assertTrue(ideal_xy < ideal_y < maximal)
        self.assertFalse(ideal_x <= ideal_y)
        self.assertFalse(ideal_y <= ideal_x)
        square = frozenset(multiplication(a, b)
                           for a in maximal for b in maximal)
        self.assertEqual(square, ideal_xy)
        self.assertTrue(all(multiplication(a, b) == 0
                            for a in square for b in maximal))

    def test_polynomial_plane_prime_chains_and_nilradical(self):
        # Independent exhaustive support check on F2[X,Y] for
        # all 1024 polynomials of total degree <=3.
        monomials = [(i, j) for i in range(4) for j in range(4-i)]
        self.assertEqual(len(monomials), 10)
        for mask in range(1 << len(monomials)):
            terms = [e for k, e in enumerate(monomials) if mask >> k & 1]
            in_x = all(i > 0 for i, j in terms)
            in_y = all(j > 0 for i, j in terms)
            in_xy = all(i > 0 and j > 0 for i, j in terms)
            in_x2 = all(i > 1 for i, j in terms)
            self.assertEqual(in_x and in_y, in_xy)
            # In char 2 square has monomials X^(2i)Y^(2j);
            # square belongs to (X^2) iff original belongs to (X).
            square_in_x2 = all(2*i > 1 for i, j in terms)
            self.assertEqual(square_in_x2, in_x)
            if not terms:
                self.assertTrue(in_x2)
        # Strict prime chains for k[X,Y]/(XY) (dimension 1):
        # (XY) < (X) < (X,Y), also (XY) < (Y) < (X,Y).
        self.assertEqual(sp.gcd(X, Y), 1)
        self.assertEqual(sp.rem(X, X*Y, X), 0)
        self.assertNotEqual(sp.Poly(X, X, Y), sp.Poly(0, X, Y))
        self.assertEqual(sp.expand(X*Y), X*Y)
        # x^2 is nilpotent but nonzero in k[X,Y]/(X^2).
        self.assertNotEqual(X, 0)
        self.assertEqual(sp.rem(X**2, X**2, X), 0)

    def test_unbounded_ideal_chain_lengths_across_artinian_family(self):
        # This deliberately is NOT a counterexample to infinite Krull
        # dimension in a single Noetherian ring: each Z/2^e has dim 0.
        for exponent in range(1, 9):
            n = 2**exponent
            divis = divisors(n)
            chain = [ideal_zn(n, 2**k)
                     for k in range(exponent, -1, -1)]
            self.assertEqual(len(chain)-1, exponent)
            self.assertTrue(all(chain[i] < chain[i+1]
                                for i in range(exponent)))
            self.assertEqual(len(divis), exponent+1)
            primes = [ideal_zn(n, d) for d in divis
                      if prime_by_definition(n, ideal_zn(n, d))]
            self.assertEqual(primes, [ideal_zn(n, 2)])
            # Every finite ring is Noetherian, and dimension remains zero.

    def test_source_hypotheses_labels_and_global_references(self):
        folder = ROOT / "chapters/pl/abstract_algebra"
        paths = sorted(folder.glob("[0-9][0-9]-*.tex"))
        self.assertEqual(len(paths), 50)
        sources = {p.name:p.read_text(encoding="utf8") for p in paths}
        labels = [m for s in sources.values()
                  for m in re.findall(r"\\label\{([^{}]+)\}", s)]
        self.assertEqual(len(labels), len(set(labels)))
        focus = (
            "13-pierscienie-noetherowskie-i-twierdzenie-hilberta.tex",
            "39-wymiar-krulla-i-lancuchy-idealow-pierwszych.tex",
        )
        self.assertEqual(
            sum(len(re.findall(r"\\label\{", sources[f]))
                for f in focus), 41)
        refs = [m for f in focus for m in re.findall(
            r"\\(?:ref|eqref|pageref|autoref)\{([^{}]+)\}", sources[f])]
        self.assertEqual(len(refs), 18)
        self.assertFalse(set(refs)-set(labels))
        for lab in ("aa:def:noether-full", "aa:tw:hilbert-basis",
                    "aa:tw:noether-localizations",
                    "aa:def:krull-dimension",
                    "aa:cor:krull-nilradical",
                    "aa:tw:krull-localization-primes",
                    "aa:tw:krull-product-dimension"):
            self.assertIn(lab, labels)


if __name__ == "__main__":
    unittest.main()
